# ============================================================== socat
GUIDES.append(dict(
    name="socat", section="1", one_line="multipurpose relay: connect two data streams",
    plain=["`socat` (SOcket CAT) connects any two 'addresses' and copies data between them: a TCP port and a file, a terminal and a network connection, one port and another port, a Unix socket and a TCP port. It is netcat with many more kinds of endpoint.",
           "The shape is `socat ADDRESS1 ADDRESS2`. Each address is a type plus options, such as `TCP-LISTEN:8080,fork,reuseaddr` or `TCP:10.10.10.5:80`.",
           "Typical uses are port forwarding, relaying between networks, TLS wrapping, serving a program on a port in a lab, and talking to Unix sockets."],
    when=["Forward a local port to a remote host (pivoting in a lab).", "Relay or log traffic between two sides.", "Wrap a plain service in TLS.", "Test a service by hand with line editing.", "Talk to a Unix socket such as /var/run/docker.sock."],
    examples=[("Connect to a port by hand", "socat - TCP:10.10.10.5:80", "- is the terminal (stdin/stdout). Type an HTTP request and see the reply."),
              ("Listen and print", "socat TCP-LISTEN:4444,reuseaddr -", "Waits for a connection on 4444 and prints what arrives: a netcat-style listener."),
              ("Forward a port", "socat TCP-LISTEN:8080,fork,reuseaddr TCP:10.10.10.5:80", "Anything sent to your port 8080 goes to 10.10.10.5:80. fork lets several connections work at once."),
              ("Serve a file", "socat TCP-LISTEN:9000,reuseaddr,fork FILE:./note.txt,rdonly", "Each connection reads the file. Useful for quick file transfer in a lab."),
              ("Receive a file", "socat TCP-LISTEN:9000,reuseaddr OPEN:received.bin,creat,trunc", "Saves whatever is sent to received.bin."),
              ("Log both directions", "socat -v TCP-LISTEN:8080,fork,reuseaddr TCP:10.10.10.5:80", "-v prints the traffic as text, so the relay doubles as a simple proxy log."),
              ("Talk to a Unix socket", "socat - UNIX-CONNECT:/var/run/docker.sock", "Lets you send raw HTTP to the Docker API on its socket."),
              ("TLS wrapper", "socat OPENSSL-LISTEN:4433,cert=server.pem,verify=0,fork TCP:127.0.0.1:8080", "Accepts TLS connections and passes them on in plain text to a local service (needs a certificate)."),
              ("A better line editor", "socat READLINE TCP:10.10.10.5:25", "READLINE gives you history and editing while talking to a service.")],
    options=[
        ("-", "Standard input and output (the terminal).", "One side of a connection."),
        ("TCP:HOST:PORT / TCP-LISTEN:PORT", "Connect to / listen on a TCP port.", "Network endpoints."),
        ("UDP:HOST:PORT / UDP-LISTEN:PORT", "UDP equivalents.", "UDP services."),
        ("OPENSSL:HOST:PORT / OPENSSL-LISTEN:PORT", "TLS client / server (options cert=, key=, cafile=, verify=).", "Encrypted links."),
        ("UNIX-CONNECT:PATH / UNIX-LISTEN:PATH", "Unix socket client / server.", "Local services."),
        ("FILE:PATH / OPEN:PATH", "Read or write a file (options creat, trunc, append, rdonly).", "File transfer."),
        ("PIPE / PTY / EXEC:CMD / SYSTEM:CMD", "Pipes, pseudo terminals and running a program as an endpoint.", "Connecting a program to a network. Powerful: use only in a lab."),
        ("READLINE", "Line editing and history on the terminal side.", "Hand-driven sessions."),
        ("fork", "After accepting a connection, fork to handle it so the listener stays up.", "Servers and relays."),
        ("reuseaddr", "Allow reuse of the port right after closing.", "Restarting a listener."),
        ("bind=IP", "Bind to a specific address.", "Listen on localhost only."),
        ("range=NET/BITS", "Accept connections only from this network.", "Restricting access."),
        ("pty, raw, echo=0, setsid, sigint, sane, stderr", "Terminal behaviour options for PTY and EXEC addresses.", "Interactive programs."),
        ("-v", "Verbose text dump of data.", "Seeing traffic."),
        ("-x", "Verbose hex dump.", "Binary traffic."),
        ("-d, -dd, -ddd", "Increase diagnostic messages.", "Debugging."),
        ("-u / -U", "Unidirectional: copy only left to right / right to left.", "One-way transfers."),
        ("-b SIZE", "Block size of transfers.", "Tuning."),
        ("-t SECONDS / -T SECONDS", "Time to wait for the second side after EOF / total inactivity timeout.", "Closing idle relays."),
        ("-lf FILE / -ls", "Log to a file / to syslog.", "Records."),
        ("-V / -h", "Version / help (-hh for all address types).", "A reminder.")],
    mistakes=["Forgetting fork on a listener: it accepts one connection and then exits.", "Forgetting reuseaddr and getting 'address already in use' on restart.", "Listening on all interfaces when localhost is enough: add bind=127.0.0.1.", "Exposing a relay to the internet by accident.", "Using EXEC/SYSTEM endpoints on machines you do not control."],
    try_=["Forward local port 8080 to a lab web server and browse it.", "Send a file between two terminals with TCP-LISTEN and OPEN.", "Use -v on a relay and read the HTTP traffic."],
    see_also="nc(1), ncat(1), ssh(1) (tunnels), openssl(1), curl(1), chisel, proxychains, tcpdump(8)."))

# ============================================================== foremost
GUIDES.append(dict(
    name="foremost", section="8", one_line="recover files by their headers and footers (file carving)",
    plain=["`foremost` scans a disk image, a memory dump or any raw data for the signature bytes at the start (header) and sometimes end (footer) of known file types and cuts the matching bytes out into files. This is called file carving, and it works even when the file system is damaged or the file was deleted.",
           "In forensics and CTFs it is a quick way to pull pictures, documents, archives and executables out of a disk image or a packet capture dump. binwalk and scalpel do similar jobs."],
    when=["Recover deleted files from a disk image.", "Extract pictures or documents hidden in a raw file.", "Carve files out of a memory dump.", "Get a quick overview of what a blob contains."],
    examples=[("Carve everything it knows", "foremost -i disk.img -o out", "-i is the input, -o an output folder (must be empty or new). It creates a folder per file type and an audit.txt summary."),
              ("Only some types", "foremost -t jpg,png,pdf -i disk.img -o out", "-t restricts to the listed types: jpg, gif, png, bmp, avi, exe, mpg, wav, riff, wmv, mov, pdf, ole, doc, zip, rar, htm, cpp."),
              ("Verbose", "foremost -v -i dump.raw -o out", "-v shows what is being found."),
              ("Quick mode", "foremost -q -i disk.img -o out", "-q searches only at the start of 512-byte blocks: faster, but misses files that do not start on a block boundary."),
              ("Audit only", "foremost -w -i disk.img -o out", "-w writes only the audit file listing what was found, without extracting."),
              ("Look at the result", "cat out/audit.txt\nls out/*", "The audit lists each hit with its offset; the per-type folders hold the files."),
              ("Check what you carved", "file out/jpg/* | head\nexiftool out/jpg/00000001.jpg", "Always check the files: carving can produce partial or false hits.")],
    options=[
        ("-i FILE", "Input file (disk image, dump). Default is standard input.", "Always."),
        ("-o DIR", "Output directory (default ./output).", "Always; it must be empty."),
        ("-t TYPES", "File types to carve, comma separated.", "Focused carving."),
        ("-c FILE", "Use another configuration file (default /etc/foremost.conf).", "Custom signatures."),
        ("-a", "Write all headers, do no error detection (carve even corrupt matches).", "Damaged files."),
        ("-b SIZE", "Block size (default 512).", "Alignment on other file systems."),
        ("-d", "Indirect block detection for UNIX file systems.", "ext2/3 images."),
        ("-k SIZE", "Chunk size for loading the image into memory.", "Large images."),
        ("-q", "Quick mode.", "Speed."),
        ("-Q", "Quiet mode: suppress most messages.", "Scripts."),
        ("-s N", "Skip N blocks at the start of the input.", "Partial scans."),
        ("-T", "Time-stamp the output directory.", "Repeated runs."),
        ("-v", "Verbose.", "Seeing progress."),
        ("-w", "Write only the audit file.", "Surveying."),
        ("-V / -h", "Version / help.", "A reminder.")],
    mistakes=["Forgetting that the output folder must not already contain files.", "Trusting carved files without checking them (fragmented files come out broken).", "Using it on a live disk instead of a copy: always work on an image.", "Expecting file names: carving recovers contents, not names.", "Skipping binwalk or scalpel when foremost finds nothing."],
    try_=["Append a JPEG and a ZIP to a binary file and carve them out with foremost.", "Compare the result with binwalk -e.", "Read audit.txt and match each offset to a file."],
    see_also="binwalk(1), scalpel(1), photorec(8), dd(1), file(1), exiftool(1), testdisk(8), sleuthkit tools."))
